	json.NewEncoder(ctx).Encode(resp)
}

// FetchURLPreview handles POST requests to fetch URL preview.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Only allow POST
	if !ctx.IsPost() {
		sendJSON(ctx, fasthttp.StatusMethodNotAllowed, PreviewResponse{Error: "Method not allowed"})
		return
	}

	var req struct {
		URL string `json:"url"`
	}

	body := ctx.PostBody()
	if err := json.Unmarshal(body, &req); err != nil {
		sendJSON(ctx, fasthttp.StatusBadRequest, PreviewResponse{Error: "Invalid JSON"})
		return
	}

	targetURL := strings.TrimSpace(req.URL)
	if targetURL == "" {
		sendJSON(ctx, fasthttp.StatusBadRequest, PreviewResponse{Error: "URL is required"})
		return
	}

	// Validate URL scheme
	parsedURL, err := url.ParseRequestURI(targetURL)
	if err != nil {
		sendJSON(ctx, fasthttp.StatusBadRequest, PreviewResponse{Error: "Invalid URL format"})
		return
	}

	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		sendJSON(ctx, fasthttp.StatusBadRequest, PreviewResponse{Error: "URL must use http or https scheme"})
		return
	}

	// Use fasthttp.Client to fetch with timeout
	client := &fasthttp.Client{
		Dial:                fasthttp.DialDualStack,
		ReadTimeout:         10 * time.Second,
		WriteTimeout:        10 * time.Second,
		MaxIdleConnDuration: 10 * time.Second,
		MaxConnsPerHost:     10,
	}

	freq := fasthttp.AcquireRequest()
	res := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(freq)
	defer fasthttp.ReleaseResponse(res)

	freq.SetRequestURI(targetURL)
	freq.Header.SetMethod("GET")
	freq.Header.Set("User-Agent", "URLPreviewBot/1.0")

	maxRedirectCounts := 10
	if err := client.DoRedirects(freq, res, maxRedirectCounts); err != nil {
		sendJSON(ctx, fasthttp.StatusBadGateway, PreviewResponse{Error: fmt.Sprintf("Failed to fetch URL: %v", err)})
		return
	}

	if res.StatusCode() != fasthttp.StatusOK {
		sendJSON(ctx, fasthttp.StatusBadGateway, PreviewResponse{Error: fmt.Sprintf("Unexpected status code: %d", res.StatusCode())})
		return
	}

	bodyBytes := res.Body()
	if len(bodyBytes) == 0 {
		sendJSON(ctx, fasthttp.StatusBadGateway, PreviewResponse{Error: "Empty response body"})
		return
	}

	title, description, err := parseHTMLPreview(bytes.NewReader(bodyBytes))
	if err != nil {
		sendJSON(ctx, fasthttp.StatusInternalServerError, PreviewResponse{Error: fmt.Sprintf("Failed to parse HTML: %v", err)})
		return
	}

	sendJSON(ctx, fasthttp.StatusOK, PreviewResponse{
		Title:       title,
		Description: description,
	})
}

// parseHTMLPreview extracts title and meta description from HTML.
func parseHTMLPreview(r io.Reader) (title, description string, err error) {
	doc, err := html.Parse(r)
	if err != nil {
		return "", "", err
	}

	var f func(*html.Node)
	f = func(n *html.Node) {
		if n.Type == html.ElementNode && n.Data == "title" {
			title = extractText(n)
		}
		if n.Type == html.ElementNode && n.Data == "meta" {
			var isDesc bool
			var content string
			for _, a := range n.Attr {
				if strings.EqualFold(a.Key, "name") && strings.EqualFold(a.Val, "description") {
					isDesc = true
				}
				if strings.EqualFold(a.Key, "content") {
					content = a.Val
				}
			}
			if isDesc && content != "" {
				description = content
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			f(c)
		}
	}
	f(doc)

	title = strings.TrimSpace(title)
	description = strings.TrimSpace(description)

	return title, description, nil
}

func extractText(n *html.Node) string {
	if n.Type == html.TextNode {
		return n.Data
	}
	var sb strings.Builder
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		sb.WriteString(extractText(c))
	}
	return sb.String()
}

func main() {
	fasthttp.ListenAndServe(":8080", FetchURLPreview)
}

