	host := parsedURL.Hostname()
	ips, err := net.LookupIP(host)
	if err != nil {
		ctx.Error("Invalid host or DNS resolution failed", fasthttp.StatusBadRequest)
		return
	}
	for _, ip := range ips {
		if isPrivateIP(ip) {
