	"strings"

	"github.com/valyala/fasthttp"
	"golang.org/x/net/html"
)

// PreviewRequest represents the incoming JSON payload.
type PreviewRequest struct {
	URL string `json:"url"`
}

// PreviewResponse represents the outgoing JSON payload.
type PreviewResponse struct {
	Title       string `json:"title,omitempty"`
	Description string `json:"description,omitempty"`
	Error       string `json:"error,omitempty"`
}

// httpClient is configured to use DualStack (IPv4/IPv6) dialing.
var httpClient = &fasthttp.Client{
	Dial:                fasthttp.DialDualStack,
	MaxResponseBodySize: 10 * 1024 * 1024, // 10MB limit to prevent OOM
}

// sendJSON is a helper to marshal and send JSON responses via fasthttp.
func sendJSON(ctx *fasthttp.RequestCtx, statusCode int, resp PreviewResponse) {
	ctx.SetStatusCode(statusCode)
	ctx.SetContentType("application/json")
	body, _ := json.Marshal(resp)
	ctx.SetBody(body)
}

// FetchURLPreview handles the POST request, fetches the URL, and extracts metadata.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	if !ctx.IsPost() {
		sendJSON(ctx, fasthttp.StatusMethodNotAllowed, PreviewResponse{Error: "Method not allowed"})
		return
	}

	var reqBody PreviewRequest
	if err := json.Unmarshal(ctx.PostBody(), &reqBody); err != nil {
		sendJSON(ctx, fasthttp.StatusBadRequest, PreviewResponse{Error: "Invalid JSON payload"})
		return
	}

	if reqBody.URL == "" {
		sendJSON(ctx, fasthttp.StatusBadRequest, PreviewResponse{Error: "URL is required"})
		return
	}

	// Basic URL validation
	parsedURL, err := url.Parse(reqBody.URL)
	if err != nil || (parsedURL.Scheme != "http" && parsedURL.Scheme != "https") {
		sendJSON(ctx, fasthttp.StatusBadRequest, PreviewResponse{Error: "Invalid URL scheme, only http and https are allowed"})
		return
	}

	req := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(req)
	res := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(res)

	req.SetRequestURI(reqBody.URL)
	req.Header.SetMethod(fasthttp.MethodGet)
	req.Header.Set("User-Agent", "Mozilla/5.0 (compatible; URLPreviewBot/1.0)")

	// Fetch the URL with redirect support
	if err := httpClient.DoRedirects(req, res, 5); err != nil {
		sendJSON(ctx, fasthttp.StatusBadGateway, PreviewResponse{Error: fmt.Sprintf("Failed to fetch URL: %v", err)})
		return
	}

	statusCode := res.StatusCode()
	if statusCode < 200 || statusCode >= 300 {
		sendJSON(ctx, fasthttp.StatusBadGateway, PreviewResponse{Error: fmt.Sprintf("Non-success status code: %d", statusCode)})
		return
	}

	body := res.Body()
	title, description := extractMeta(body)

	sendJSON(ctx, fasthttp.StatusOK, PreviewResponse{
		Title:       title,
		Description: description,
	})
}

// extractMeta parses the HTML body and extracts the title and meta description.
func extractMeta(body []byte) (string, string) {
	doc, err := html.Parse(bytes.NewReader(body))
	if err != nil {
		return "", ""
	}

	var title, description string

	var traverse func(*html.Node)
	traverse = func(n *html.Node) {
		if n.Type == html.ElementNode {
			if n.Data == "title" {
				title = extractText(n)
			} else if n.Data == "meta" {
				var name, content string
				for _, attr := range n.Attr {
					if strings.EqualFold(attr.Key, "name") {
						name = attr.Val
					} else if strings.EqualFold(attr.Key, "content") {
						content = attr.Val
					}
				}
				if strings.EqualFold(name, "description") {
					description = content
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			traverse(c)
		}
	}

	traverse(doc)
	return strings.TrimSpace(title), strings.TrimSpace(description)
}

// extractText recursively extracts text content from an HTML node.
func extractText(n *html.Node) string {
	if n.Type == html.TextNode {
		return n.Data
	}
	var sb strings.Builder
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		sb.WriteString(extractText(c))
	}
	return sb.String()
}

func main() {
	// Start the fasthttp server on port 8080
	fasthttp.ListenAndServe(":8080", FetchURLPreview)
}

