var (
	titleRegex   = regexp.MustCompile(`(?is)<title[^>]*>(.*?)</title>`)
	metaRegex    = regexp.MustCompile(`(?is)<meta[^>]+>`)
	nameRegex    = regexp.MustCompile(`(?i)name=["']description["']`)
	contentRegex = regexp.MustCompile(`(?i)content=["'](.*?)["']`)
)

// parseHTMLPreview extracts title and meta description from HTML safely using regex and limits memory usage.
func parseHTMLPreview(r io.Reader) (title, description string, err error) {
	// Limit reading to 1MB to avoid excessive memory consumption on huge HTML pages
	limitedReader := io.LimitReader(r, 1024*1024)
	b, err := io.ReadAll(limitedReader)
	if err != nil {
		return "", "", err
	}
	content := string(b)

	titleMatch := titleRegex.FindStringSubmatch(content)
	if len(titleMatch) > 1 {
		title = strings.TrimSpace(titleMatch[1])
	}

	metaMatches := metaRegex.FindAllString(content, -1)
	for _, m := range metaMatches {
		if nameRegex.MatchString(m) {
			contentMatch := contentRegex.FindStringSubmatch(m)
			if len(contentMatch) > 1 {
				description = strings.TrimSpace(contentMatch[1])
				break
			}
		}
	}

	return title, description, nil
}

