package main

import (
	"bytes"
	"encoding/json"
	"strings"

	"github.com/valyala/fasthttp"
	"golang.org/x/net/html"
)

// FetchURLPreview handles POST requests to fetch a URL, parse its HTML,
// and return the title and meta description as JSON.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	if !ctx.IsPost() {
		ctx.Error("Method not allowed", fasthttp.StatusMethodNotAllowed)
		return
	}

	var reqData struct {
		URL string `json:"url"`
	}

	if err := json.Unmarshal(ctx.PostBody(), &reqData); err != nil || reqData.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.Write([]byte(`{"error":"invalid request body or missing url"}`))
		return
	}

	// Initialize fasthttp client with DialDualStack as required
	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	req := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(req)
	res := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(res)

	req.SetRequestURI(reqData.URL)
	req.Header.SetMethod(fasthttp.MethodGet)

	// Fetch the URL using DoRedirects
	if err := client.DoRedirects(req, res, 5); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetContentType("application/json")
		ctx.Write([]byte(`{"error":"failed to fetch url"}`))
		return
	}

	body := res.Body()
	doc, err := html.Parse(bytes.NewReader(body))
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		ctx.Write([]byte(`{"error":"failed to parse html"}`))
		return
	}

	var title, description string

	// Recursive function to traverse the HTML nodes
	var f func(*html.Node)
	f = func(n *html.Node) {
		if n.Type == html.ElementNode && n.Data == "title" {
			var sb strings.Builder
			for c := n.FirstChild; c != nil; c = c.NextSibling {
				if c.Type == html.TextNode {
					sb.WriteString(c.Data)
				}
			}
			title = strings.TrimSpace(sb.String())
		}

		if n.Type == html.ElementNode && n.Data == "meta" {
			var name, content string
			for _, a := range n.Attr {
				if strings.EqualFold(a.Key, "name") {
					name = a.Val
				}
				if strings.EqualFold(a.Key, "content") {
					content = a.Val
				}
			}
			if strings.EqualFold(name, "description") {
				description = content
			}
		}

		for c := n.FirstChild; c != nil; c = c.NextSibling {
			f(c)
		}
	}
	f(doc)

	respData := map[string]string{
		"title":       title,
		"description": description,
	}

	respBytes, err := json.Marshal(respData)
	if err != nil {
		ctx.Error("Internal Server Error", fasthttp.StatusInternalServerError)
		return
	}

	ctx.SetContentType("application/json")
	ctx.Write(respBytes)
}

func main() {
	// Start the fasthttp server
	fasthttp.ListenAndServe(":8080", FetchURLPreview)
}

