// safeDial prevents SSRF by resolving DNS and blocking private/internal IPs.
// It also dials the resolved IP directly to prevent DNS rebinding attacks.
func safeDial(addr string) (net.Conn, error) {
	host, port, err := net.SplitHostPort(addr)
	if err != nil {
		return nil, fmt.Errorf("invalid address format")
	}

	// Clean up IPv6 brackets if present
	host = strings.TrimPrefix(host, "[")
	host = strings.TrimSuffix(host, "]")

