import (
	"bytes"
	"encoding/json"
	"log"
	"strings"
	"time"

	"github.com/valyala/fasthttp"
	"golang.org/x/net/html"
)

// URLRequest represents the incoming JSON payload.
type URLRequest struct {
	URL string `json:"url"`
}

// URLPreviewResponse represents the outgoing JSON payload.
type URLPreviewResponse struct {
	Title       string `json:"title,omitempty"`
	Description string `json:"description,omitempty"`
	Error       string `json:"error,omitempty"`
}

// httpClient is configured with DualStack dialing and a 3-second timeout.
var httpClient = &fasthttp.Client{
	Dial:                fasthttp.DialDualStack,
	ReadTimeout:         3 * time.Second,
	WriteTimeout:        3 * time.Second,
	MaxResponseBodySize: 10 * 1024 * 1024, // 10MB limit to prevent OOM
}

// FetchURLPreview handles the POST request, fetches the URL, and extracts metadata.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	ctx.SetContentType("application/json")

	// Ensure the request method is POST
	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		resp, _ := json.Marshal(URLPreviewResponse{Error: "Method not allowed"})
		ctx.SetBody(resp)
		return
	}

	// Parse the incoming JSON body
	var payload URLRequest
	if err := json.Unmarshal(ctx.PostBody(), &payload); err != nil || payload.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		resp, _ := json.Marshal(URLPreviewResponse{Error: "Invalid JSON or missing 'url' field"})
		ctx.SetBody(resp)
		return
	}

	// Acquire request and response objects from the pool
	req := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(req)
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(resp)

	// Configure the request
	req.SetRequestURI(payload.URL)
	req.Header.SetMethod(fasthttp.MethodGet)

	// Fetch the URL with a maximum of 5 redirects
	if err := httpClient.DoRedirects(req, resp, 5); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		respBody, _ := json.Marshal(URLPreviewResponse{Error: "Failed to fetch URL: " + err.Error()})
		ctx.SetBody(respBody)
		return
	}

	// Parse the HTML and extract title and meta description
	body := resp.Body()
	title, description := extractMeta(body)

	// Return the successful JSON response
	ctx.SetStatusCode(fasthttp.StatusOK)
	respBody, _ := json.Marshal(URLPreviewResponse{
		Title:       title,
		Description: description,
	})
	ctx.SetBody(respBody)
}

// extractMeta parses the HTML body and extracts the title and meta description.
func extractMeta(body []byte) (string, string) {
	doc, err := html.Parse(bytes.NewReader(body))
	if err != nil {
		return "", ""
	}

	var title, description string

	var traverse func(*html.Node)
	traverse = func(n *html.Node) {
		if n.Type == html.ElementNode {
			if n.Data == "title" {
				title = extractText(n)
			} else if n.Data == "meta" {
				var name, content string
				for _, attr := range n.Attr {
					if strings.EqualFold(attr.Key, "name") {
						name = attr.Val
					} else if strings.EqualFold(attr.Key, "content") {
						content = attr.Val
					}
				}
				if strings.EqualFold(name, "description") {
					description = content
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			traverse(c)
		}
	}

	traverse(doc)
	return strings.TrimSpace(title), strings.TrimSpace(description)
}

// extractText recursively extracts text content from an HTML node.
func extractText(n *html.Node) string {
	var text string
	if n.Type == html.TextNode {
		return n.Data
	}
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		text += extractText(c)
	}
	return text
}

func main() {
	log.Println("Starting URL Preview server on :8080")
	if err := fasthttp.ListenAndServe(":8080", FetchURLPreview); err != nil {
		log.Fatalf("Error in ListenAndServe: %s", err)
	}
}

