// PreviewResponse represents the JSON response structure.
type PreviewResponse struct {
	Title       string `json:"title,omitempty"`
	Description string `json:"description,omitempty"`
	Error       string `json:"error,omitempty"`
}

// FetchURLPreview handles POST requests to fetch URL preview.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	sendError := func(statusCode int, errMsg string) {
		ctx.SetStatusCode(statusCode)
		ctx.SetContentType("application/json; charset=utf-8")
		json.NewEncoder(ctx).Encode(PreviewResponse{Error: errMsg})
	}

	// Only allow POST
	if !ctx.IsPost() {
		sendError(fasthttp.StatusMethodNotAllowed, "Method not allowed")
		return
	}

	var req struct {
		URL string `json:"url"`
	}

	body := ctx.PostBody()
	if err := json.Unmarshal(body, &req); err != nil {
		sendError(fasthttp.StatusBadRequest, "Invalid JSON")
		return
	}

	targetURL := strings.TrimSpace(req.URL)
	if targetURL == "" {
		sendError(fasthttp.StatusBadRequest, "URL is required")
		return
	}

	// Validate URL scheme
	parsedURL, err := url.ParseRequestURI(targetURL)
	if err != nil {
		sendError(fasthttp.StatusBadRequest, "Invalid URL format")
		return
	}

	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		sendError(fasthttp.StatusBadRequest, "URL must use http or https scheme")
		return
	}

	// Use fasthttp.Client to fetch with timeout
	client := &fasthttp.Client{
		DialDualStack:       true,
		ReadTimeout:         10 * time.Second,
		WriteTimeout:        10 * time.Second,
		MaxIdleConnDuration: 10 * time.Second,
		MaxConnsPerHost:     10,
	}

	freq := fasthttp.AcquireRequest()
	res := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(freq)
	defer fasthttp.ReleaseResponse(res)

	freq.SetRequestURI(targetURL)
	freq.Header.SetMethod("GET")
	freq.Header.Set("User-Agent", "URLPreviewBot/1.0")
	// Prevent compressed responses to simplify HTML parsing
	freq.Header.Set("Accept-Encoding", "identity")

	maxRedirectCounts := 10
	if err := client.DoRedirects(freq, res, maxRedirectCounts); err != nil {
		sendError(fasthttp.StatusBadGateway, fmt.Sprintf("Failed to fetch URL: %v", err))
		return
	}

	if res.StatusCode() != fasthttp.StatusOK {
		sendError(fasthttp.StatusBadGateway, fmt.Sprintf("Unexpected status code: %d", res.StatusCode()))
		return
	}

	bodyBytes := res.Body()
	if len(bodyBytes) == 0 {
		sendError(fasthttp.StatusBadGateway, "Empty response body")
		return
	}

	title, description, err := parseHTMLPreview(bytes.NewReader(bodyBytes))
	if err != nil {
		sendError(fasthttp.StatusInternalServerError, fmt.Sprintf("Failed to parse HTML: %v", err))
		return
	}

	resp := PreviewResponse{
		Title:       title,
		Description: description,
	}

	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json; charset=utf-8")
	if err := json.NewEncoder(ctx).Encode(resp); err != nil {
		// Headers might already be sent, so we just return
		return
	}
}

// parseHTMLPreview extracts title and meta description from HTML.
func parseHTMLPreview(r io.Reader) (title, description string, err error) {
	tokenizer := html.NewTokenizer(r)
	for {
		tt := tokenizer.Next()
		switch tt {
		case html.ErrorToken:
			err := tokenizer.Err()
			if err == io.EOF {
				return title, description, nil
			}
			return title, description, err
		case html.StartTagToken, html.SelfClosingTagToken:
			tn, hasAttr := tokenizer.TagName()
			tagName := string(tn)

			if tagName == "title" && title == "" {
				var titleBuilder strings.Builder
				for {
					tt := tokenizer.Next()
					if tt == html.TextToken {
						titleBuilder.Write(tokenizer.Text())
					} else if tt == html.EndTagToken {
						tn, _ := tokenizer.TagName()
						if string(tn) == "title" {
							break
						}
					} else if tt == html.ErrorToken {
						break
					}
				}
				title = html.UnescapeString(strings.TrimSpace(titleBuilder.String()))
			}

			if tagName == "meta" && hasAttr {
				var name, content string
				for {
					key, val, more := tokenizer.TagAttr()
					k := strings.ToLower(string(key))
					v := string(val)
					if k == "name" {
						name = strings.ToLower(v)
					}
					if k == "content" {
						content = v
					}
					if !more {
						break
					}
				}
				if name == "description" && description == "" {
					description = html.UnescapeString(content)
				}
			}
		}
	}
}

