		ctx.Error("Empty response body", fasthttp.StatusBadGateway)
		return
	}

	title, description, err := parseHTMLPreview(bytes.NewReader(bodyBytes))
	if err != nil {
		ctx.Error(fmt.Sprintf("Failed to parse HTML: %v", err), fasthttp.StatusInternalServerError)
		return
	}

	resp := PreviewResponse{
		Title:       title,
		Description: description,
	}

	ctx.SetContentType("application/json; charset=utf-8")
	if err := json.NewEncoder(ctx).Encode(resp); err != nil {
		ctx.Error("Failed to encode response", fasthttp.StatusInternalServerError)
		return
	}
}

// parseHTMLPreview extracts title and meta description from HTML safely.
func parseHTMLPreview(r io.Reader) (title, description string, err error) {
	// Limit reading to 1MB to avoid excessive memory consumption during parsing
	limitedReader := io.LimitReader(r, 1024*1024)
	body, err := io.ReadAll(limitedReader)
	if err != nil {
		return "", "", err
	}

	if match := titleRe.FindSubmatch(body); len(match) > 1 {
		title = html.UnescapeString(strings.TrimSpace(string(match[1])))
	}

	metas := metaRe.FindAll(body, -1)
	for _, meta := range metas {
		metaLower := bytes.ToLower(meta)
		if bytes.Contains(metaLower, []byte(`name="description"`)) || bytes.Contains(metaLower, []byte(`name='description'`)) {
			if contentMatch := contentRe.FindSubmatch(meta); len(contentMatch) > 1 {
				description = html.UnescapeString(strings.TrimSpace(string(contentMatch[1])))
				break
			}
		}
	}

	return title, description, nil
}

