// httpClient is configured with DialDualStack and a 3-second timeout.
var httpClient = &fasthttp.Client{
	Dial:         fasthttp.DialDualStack,
	ReadTimeout:  3 * time.Second,
	WriteTimeout: 3 * time.Second,
}

// extractMeta parses HTML content and extracts the page title and meta description.
func extractMeta(body []byte) (title, description string) {
	tokenizer := html.NewTokenizer(bytes.NewReader(body))
	inTitle := false

	for {
		tt := tokenizer.Next()
		switch tt {
		case html.ErrorToken:
			return title, description

		case html.TextToken:
			if inTitle && title == "" {
				title = strings.TrimSpace(tokenizer.Token().Data)
			}

		case html.StartTagToken:
			t := tokenizer.Token()
			if t.Data == "title" && title == "" {
				inTitle = true
			}
			if t.Data == "meta" {
				desc := extractMetaDescription(t.Attr)
				if desc != "" && description == "" {
					description = desc
				}
			}

		case html.SelfClosingTagToken:
			t := tokenizer.Token()
			if t.Data == "meta" {
				desc := extractMetaDescription(t.Attr)
				if desc != "" && description == "" {
					description = desc
				}
			}

		case html.EndTagToken:
			t := tokenizer.Token()
			if t.Data == "title" {
				inTitle = false
			}
		}
	}
}

// extractMetaDescription checks if a meta tag's attributes contain name="description"
// and returns the corresponding content value.
func extractMetaDescription(attrs []html.Attribute) string {
	var name, content string
	for _, attr := range attrs {
		if strings.EqualFold(attr.Key, "name") {
			name = strings.ToLower(strings.TrimSpace(attr.Val))
		}
		if strings.EqualFold(attr.Key, "content") {
			content = attr.Val
		}
	}
	if name == "description" {
		return content
	}
	return ""
}

// FetchURLPreview handles POST requests, fetches the given URL, parses the HTML,
// and returns the extracted title and meta description as JSON.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	ctx.SetContentType("application/json")

	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		resp, _ := json.Marshal(ErrorResponse{Error: "method not allowed"})
		ctx.SetBody(resp)
		return
	}

	var reqBody URLRequest
	if err := json.Unmarshal(ctx.PostBody(), &reqBody); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		resp, _ := json.Marshal(ErrorResponse{Error: "invalid request body"})
		ctx.SetBody(resp)
		return
	}

	if reqBody.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		resp, _ := json.Marshal(ErrorResponse{Error: "url is required"})
		ctx.SetBody(resp)
		return
	}

	req := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(req)

	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(resp)

	req.SetRequestURI(reqBody.URL)
	req.Header.SetMethod("GET")

	if err := httpClient.DoRedirects(req, resp, 5); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		respBody, _ := json.Marshal(ErrorResponse{Error: "failed to fetch url: " + err.Error()})
		ctx.SetBody(respBody)
		return
	}

	body := resp.Body()
	title, description := extractMeta(body)

	result := URLPreviewResponse{
		Title:       title,
		Description: description,
	}

	respBody, _ := json.Marshal(result)
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetBody(respBody)
}

func main() {
	fasthttp.ListenAndServe(":8080", FetchURLPreview)
}

