// PreviewResponse represents the JSON response structure.
type PreviewResponse struct {
	Title       string `json:"title,omitempty"`
	Description string `json:"description,omitempty"`
	Error       string `json:"error,omitempty"`
}

var privateRanges []*net.IPNet

func init() {
	cidrs := []string{
		"127.0.0.0/8",    // Loopback
		"10.0.0.0/8",     // Private
		"172.16.0.0/12",  // Private
		"192.168.0.0/16", // Private
		"169.254.0.0/16", // Link-local
		"100.64.0.0/10",  // Carrier-grade NAT
		"192.0.0.0/24",   // IETF Protocol Assignments
		"192.0.2.0/24",   // TEST-NET-1
		"198.51.100.0/24",// TEST-NET-2
		"203.0.113.0/24", // TEST-NET-3
		"224.0.0.0/4",    // Multicast
		"240.0.0.0/4",    // Reserved
		"255.255.255.255/32", // Broadcast
		"::1/128",        // Loopback
		"fc00::/7",       // Unique local address
		"fe80::/10",      // Link-local
		"ff00::/8",       // Multicast
		"2001:db8::/32",  // Documentation
	}
	for _, cidr := range cidrs {
		_, network, err := net.ParseCIDR(cidr)
		if err == nil {
			privateRanges = append(privateRanges, network)
		}
	}
}

func normalizeIP(ip net.IP) net.IP {
	if v4 := ip.To4(); v4 != nil {
		return v4
	}
	return ip
}

func isPrivateIP(ip net.IP) bool {
	ip = normalizeIP(ip)
	if ip.IsUnspecified() {
		return true
	}
	for _, network := range privateRanges {
		if network.Contains(ip) {
			return true
		}
	}
	return false
}

// safeDial prevents SSRF by resolving DNS and verifying the IP is public before connecting.
// This also protects against DNS rebinding and redirects to internal networks.
func safeDial(addr string) (net.Conn, error) {
	host, port, err := net.SplitHostPort(addr)
	if err != nil {
		return nil, err
	}

	ips, err := net.LookupIP(host)
	if err != nil {
		if parsedIP := net.ParseIP(host); parsedIP != nil {
			ips = []net.IP{parsedIP}
		} else {
			return nil, fmt.Errorf("DNS lookup failed: %w", err)
		}
	}

	var safeIP net.IP
	for _, ip := range ips {
		if !isPrivateIP(ip) {
			safeIP = ip
			break
		}
	}

	if safeIP == nil {
		return nil, fmt.Errorf("access to private or reserved IP is forbidden")
	}

	dialAddr := net.JoinHostPort(safeIP.String(), port)
	dialer := &net.Dialer{
		Timeout: 10 * time.Second,
	}
	return dialer.Dial("tcp", dialAddr)
}

var (
	titleRe = regexp.MustCompile(`(?is)<title[^>]*>(.*?)</title>`)
	descRe1 = regexp.MustCompile(`(?i)<meta[^>]+name\s*=\s*["']description["'][^>]+content\s*=\s*["'](.*?)["']`)
	descRe2 = regexp.MustCompile(`(?i)<meta[^>]+content\s*=\s*["'](.*?)["'][^>]+name\s*=\s*["']description["']`)
)

// FetchURLPreview handles POST requests to fetch URL preview.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Only allow POST
	if !ctx.IsPost() {
		ctx.Error("Method not allowed", fasthttp.StatusMethodNotAllowed)
		return
	}

	var req struct {
		URL string `json:"url"`
	}

	body := ctx.PostBody()
	if err := json.Unmarshal(body, &req); err != nil {
		ctx.Error("Invalid JSON", fasthttp.StatusBadRequest)
		return
	}

	targetURL := strings.TrimSpace(req.URL)
	if targetURL == "" {
		ctx.Error("URL is required", fasthttp.StatusBadRequest)
		return
	}

	// Validate URL scheme
	parsedURL, err := url.ParseRequestURI(targetURL)
	if err != nil {
		ctx.Error("Invalid URL format", fasthttp.StatusBadRequest)
		return
	}

	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		ctx.Error("URL must use http or https scheme", fasthttp.StatusBadRequest)
		return
	}

	// Use fasthttp.Client to fetch with timeout and SSRF protection
	client := &fasthttp.Client{
		Dial:                safeDial,
		ReadTimeout:         10 * time.Second,
		WriteTimeout:        10 * time.Second,
		MaxIdleConnDuration: 10 * time.Second,
		MaxConnsPerHost:     10,
		MaxResponseBodySize: 10 * 1024 * 1024, // 10 MB limit to prevent OOM
	}

	freq := fasthttp.AcquireRequest()
	res := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(freq)
	defer fasthttp.ReleaseResponse(res)

	freq.SetRequestURI(targetURL)
	freq.Header.SetMethod("GET")
	freq.Header.Set("User-Agent", "URLPreviewBot/1.0")

	maxRedirectCounts := 10
	if err := client.DoRedirects(freq, res, maxRedirectCounts); err != nil {
		ctx.Error(fmt.Sprintf("Failed to fetch URL: %v", err), fasthttp.StatusBadGateway)
		return
	}

	if res.StatusCode() != fasthttp.StatusOK {
		ctx.Error(fmt.Sprintf("Unexpected status code: %d", res.StatusCode()), fasthttp.StatusBadGateway)
		return
	}

	bodyBytes := res.Body()
	if len(bodyBytes) == 0 {
		ctx.Error("Empty response body", fasthttp.StatusBadGateway)
		return
	}

	title, description, err := parseHTMLPreview(bytes.NewReader(bodyBytes))
	if err != nil {
		ctx.Error(fmt.Sprintf("Failed to parse HTML: %v", err), fasthttp.StatusInternalServerError)
		return
	}

	resp := PreviewResponse{
		Title:       title,
		Description: description,
	}

	ctx.SetContentType("application/json; charset=utf-8")
	if err := json.NewEncoder(ctx).Encode(resp); err != nil {
		ctx.Error("Failed to encode response", fasthttp.StatusInternalServerError)
		return
	}
}

// parseHTMLPreview extracts title and meta description from HTML.
func parseHTMLPreview(r io.Reader) (title, description string, err error) {
	// Limit reading to prevent OOM just in case
	body, err := io.ReadAll(io.LimitReader(r, 10*1024*1024))
	if err != nil {
		return "", "", err
	}

	if m := titleRe.FindSubmatch(body); m != nil {
		title = strings.TrimSpace(string(m[1]))
	}

	if m := descRe1.FindSubmatch(body); m != nil {
		description = strings.TrimSpace(string(m[1]))
	} else if m := descRe2.FindSubmatch(body); m != nil {
		description = strings.TrimSpace(string(m[1]))
	}

	return title, description, nil
}

