import (
	"bytes"
	"encoding/json"
	"strings"

	"github.com/valyala/fasthttp"
	"golang.org/x/net/html"
)

var httpClient = &fasthttp.Client{
	Dial: fasthttp.DialDualStack,
}

type RequestPayload struct {
	URL string `json:"url"`
}

type ResponsePayload struct {
	Title       string `json:"title"`
	Description string `json:"description"`
}

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	ctx.SetContentType("application/json")

	var payload RequestPayload
	if err := json.Unmarshal(ctx.PostBody(), &payload); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.Write([]byte(`{"error":"invalid json body"}`))
		return
	}

	if payload.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.Write([]byte(`{"error":"url is required"}`))
		return
	}

	req := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(req)
	res := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(res)

	req.SetRequestURI(payload.URL)
	req.Header.SetMethod(fasthttp.MethodGet)

	if err := httpClient.DoRedirects(req, res, 10); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		resp, _ := json.Marshal(map[string]string{"error": err.Error()})
		ctx.Write(resp)
		return
	}

	title, desc := parseHTML(res.Body())

	respPayload := ResponsePayload{
		Title:       title,
		Description: desc,
	}

	respBytes, _ := json.Marshal(respPayload)
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.Write(respBytes)
}

func parseHTML(body []byte) (string, string) {
	doc, err := html.Parse(bytes.NewReader(body))
	if err != nil {
		return "", ""
	}

	var title, desc string
	var traverse func(*html.Node)
	traverse = func(n *html.Node) {
		if n.Type == html.ElementNode {
			if n.Data == "title" {
				title = extractText(n)
			} else if n.Data == "meta" {
				var name, content string
				for _, attr := range n.Attr {
					if strings.EqualFold(attr.Key, "name") {
						name = attr.Val
					}
					if strings.EqualFold(attr.Key, "content") {
						content = attr.Val
					}
				}
				if strings.EqualFold(name, "description") {
					desc = content
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			traverse(c)
		}
	}
	traverse(doc)
	return strings.TrimSpace(title), strings.TrimSpace(desc)
}

func extractText(n *html.Node) string {
	var text string
	if n.Type == html.TextNode {
		return n.Data
	}
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		text += extractText(c)
	}
	return text
}

func main() {
	fasthttp.ListenAndServe(":8080", FetchURLPreview)
}

