		}
	}
	return false
}

// safeDial is a custom dialer that prevents SSRF by validating resolved IPs before connecting.
func safeDial(addr string) (net.Conn, error) {
	host, port, err := net.SplitHostPort(addr)
	if err != nil {
		return nil, err
	}

	ips, err := net.LookupIP(host)
	if err != nil {
		return nil, fmt.Errorf("DNS lookup failed: %w", err)
	}

	for _, ip := range ips {
		if isPrivateIP(ip) {
			return nil, fmt.Errorf("access to private network is not allowed")
		}
	}

	// Connect to the first valid IP to prevent DNS rebinding attacks
	return net.DialTimeout("tcp", net.JoinHostPort(ips[0].String(), port), 10*time.Second)
