	"log"
	"strings"

	"github.com/valyala/fasthttp"
	"golang.org/x/net/html"
)

// URLRequest represents the incoming JSON payload.
type URLRequest struct {
	URL string `json:"url"`
}

// URLPreviewResponse represents the outgoing JSON payload.
type URLPreviewResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
	Error       string `json:"error,omitempty"`
}

// httpClient is configured to use DialDualStack as required.
var httpClient = &fasthttp.Client{
	Dial: fasthttp.DialDualStack,
}

// FetchURLPreview handles the POST request, fetches the URL, and extracts metadata.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	ctx.SetContentType("application/json")

	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		resp, _ := json.Marshal(URLPreviewResponse{Error: "method not allowed"})
		ctx.SetBody(resp)
		return
	}

	var reqBody URLRequest
	if err := json.Unmarshal(ctx.PostBody(), &reqBody); err != nil || reqBody.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		resp, _ := json.Marshal(URLPreviewResponse{Error: "invalid request body or missing url"})
		ctx.SetBody(resp)
		return
	}

	req := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(req)
	res := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(res)

	req.SetRequestURI(reqBody.URL)
	req.Header.SetMethod(fasthttp.MethodGet)

	// Fetch the URL using DoRedirects as required.
	if err := httpClient.DoRedirects(req, res, 10); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		resp, _ := json.Marshal(URLPreviewResponse{Error: "failed to fetch url: " + err.Error()})
		ctx.SetBody(resp)
		return
	}

	title, description := extractMeta(res.Body())

	resp, _ := json.Marshal(URLPreviewResponse{
		Title:       title,
		Description: description,
	})
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetBody(resp)
}

// extractMeta parses the HTML body and extracts the title and meta description.
func extractMeta(body []byte) (string, string) {
	doc, err := html.Parse(strings.NewReader(string(body)))
	if err != nil {
		return "", ""
	}

	var title, description string

	var traverse func(*html.Node)
	traverse = func(n *html.Node) {
		if n.Type == html.ElementNode {
			if n.Data == "title" {
				title = getTextContent(n)
			} else if n.Data == "meta" {
				var isDesc bool
				var content string
				for _, attr := range n.Attr {
					if strings.EqualFold(attr.Key, "name") && strings.EqualFold(attr.Val, "description") {
						isDesc = true
					}
					if strings.EqualFold(attr.Key, "content") {
						content = attr.Val
					}
				}
				if isDesc && description == "" {
					description = content
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			traverse(c)
		}
	}
	traverse(doc)

	return strings.TrimSpace(title), strings.TrimSpace(description)
}

// getTextContent recursively extracts all text content from an HTML node.
func getTextContent(n *html.Node) string {
	if n.Type == html.TextNode {
		return n.Data
	}
	var sb strings.Builder
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		sb.WriteString(getTextContent(c))
	}
	return sb.String()
}

