// parseHTMLPreview extracts title and meta description from HTML.
func parseHTMLPreview(r io.Reader) (title, description string, err error) {
	// Limit read to 5MB to prevent OOM/DoS from massive HTML payloads
	limitedReader := io.LimitReader(r, 5*1024*1024)
	body, err := io.ReadAll(limitedReader)
	if err != nil {
		return "", "", err
	}

	bodyStr := string(body)

	titleMatch := titleRegex.FindStringSubmatch(bodyStr)
	if len(titleMatch) > 1 {
		title = strings.TrimSpace(titleMatch[1])
	}

	descMatch := metaRegex.FindStringSubmatch(bodyStr)
	if len(descMatch) > 1 {
		description = strings.TrimSpace(descMatch[1])
	} else {
		descMatch2 := metaRegex2.FindStringSubmatch(bodyStr)
		if len(descMatch2) > 1 {
			description = strings.TrimSpace(descMatch2[1])
		}
	}

	return title, description, nil
}

