var httpClient = &fasthttp.Client{
	Dial: fasthttp.DialDualStack,
}

func extractMeta(body []byte) (title, description string) {
	tokenizer := html.NewTokenizer(bytes.NewReader(body))
	for {
		tt := tokenizer.Next()
		switch tt {
		case html.ErrorToken:
			return title, description
		case html.StartTagToken, html.SelfClosingTagToken:
			tn, hasAttr := tokenizer.TagName()
			tagName := string(tn)

			if tagName == "title" && tt == html.StartTagToken {
				if tokenizer.Next() == html.TextToken {
					title = stdhtml.UnescapeString(strings.TrimSpace(string(tokenizer.Text())))
				}
			}

			if tagName == "meta" && hasAttr {
				var name, content string
				for {
					key, val, more := tokenizer.TagAttr()
					k := strings.ToLower(string(key))
					v := string(val)
					if k == "name" || k == "property" {
						name = strings.ToLower(v)
					}
					if k == "content" {
						content = v
					}
					if !more {
						break
					}
				}
				if name == "description" || name == "og:description" {
					description = stdhtml.UnescapeString(content)
				}
			}
		}
	}
}

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	ctx.SetContentType("application/json")

	var reqData struct {
		URL string `json:"url"`
	}

	if err := json.Unmarshal(ctx.PostBody(), &reqData); err != nil || reqData.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.Write([]byte(`{"error":"invalid request body or missing url"}`))
		return
	}

	req := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(req)
	res := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(res)

	req.SetRequestURI(reqData.URL)
	req.Header.SetMethod(fasthttp.MethodGet)
	req.Header.SetUserAgent("Mozilla/5.0 (compatible; URLPreviewBot/1.0)")

	err := httpClient.DoRedirects(req, res, 5)
