		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		resp, _ := json.Marshal(map[string]string{"error": err.Error()})
		ctx.Write(resp)
		return
	}

	title, desc := extractMeta(res.Body())

	respData := map[string]string{
		"title":       title,
		"description": desc,
	}
	resp, _ := json.Marshal(respData)
	ctx.Write(resp)
}

func main() {
