		return
	}
}

// parseHTMLPreview extracts title and meta description from HTML.
func parseHTMLPreview(r io.Reader) (title, description string, err error) {
	tokenizer := html.NewTokenizer(r)
	for {
		tt := tokenizer.Next()
		switch tt {
		case html.ErrorToken:
			err = tokenizer.Err()
			if err == io.EOF {
				err = nil
			}
			return title, description, err
		case html.StartTagToken, html.SelfClosingTagToken:
			tn, hasAttr := tokenizer.TagName()
			tagName := string(tn)
			if tagName == "title" {
				for {
					ntt := tokenizer.Next()
					if ntt == html.TextToken {
						title = strings.TrimSpace(string(tokenizer.Text()))
						break
					} else if ntt == html.EndTagToken || ntt == html.ErrorToken {
						break
					}
				}
			} else if tagName == "meta" && hasAttr {
				var name, content string
				for {
					key, val, more := tokenizer.TagAttr()
					k := strings.ToLower(string(key))
					v := string(val)
					if k == "name" {
						name = strings.ToLower(strings.TrimSpace(v))
					} else if k == "content" {
						content = strings.TrimSpace(v)
					}
					if !more {
						break
					}
				}
				if name == "description" {
					description = content
				}
			}
		}
		// Optimization: stop early if both are found
		if title != "" && description != "" {
			return title, description, nil
		}
	}
}

