	ReadTimeout:         3 * time.Second,
	WriteTimeout:        3 * time.Second,
	MaxResponseBodySize: 10 * 1024 * 1024, // 10MB limit to prevent OOM
}

// FetchURLPreview handles the POST request, fetches the URL, and parses the HTML
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	ctx.SetContentType("application/json")

	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		b, _ := json.Marshal(URLPreview{Error: "Method not allowed"})
		ctx.SetBody(b)
		return
	}

	var reqBody URLRequest
	if err := json.Unmarshal(ctx.PostBody(), &reqBody); err != nil || reqBody.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		b, _ := json.Marshal(URLPreview{Error: "Invalid request body or missing url"})
		ctx.SetBody(b)
		return
	}

	url := reqBody.URL
	if !strings.HasPrefix(url, "http://") && !strings.HasPrefix(url, "https://") {
		url = "http://" + url
	}

	req := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(req)
	res := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(res)

	req.SetRequestURI(url)
	req.Header.SetMethod(fasthttp.MethodGet)

